import type { FilterForm } from 'models/Filters';

const ALL = 'All';

const getStringFilterValue = (
  applied: FilterForm,
  key: string,
  fallback = ALL,
): string => {
  const value = applied[key];

  return typeof value === 'string' ? value : fallback;
};

const getDimensionFilterValue = (
  applied: FilterForm,
  activeSubFilters: Record<string, unknown> | undefined,
  key: string,
): string => {
  const subFilterValue = activeSubFilters?.[key];

  if (typeof subFilterValue === 'string') {
    return subFilterValue;
  }

  return getStringFilterValue(applied, key);
};

export interface CommercialResultsSubFilters {
  period_type: string;
  country: string;
  region: string;
  brand: string;
  sub_brand: string;
  sku: string;
  category: string;
  non_alcoholic: string;
  pack_type: string;
  growth_levers: string;
  beer_price_segment: string;
  portfolios: string;
  channel: string;
}

export function getCommercialResultsSubFilters(
  applied: FilterForm,
  activeSubFilters?: Record<string, unknown>,
): CommercialResultsSubFilters {
  return {
    period_type: getStringFilterValue(applied, 'periods', 'YTD'),
    country: getStringFilterValue(applied, 'country'),
    region: getDimensionFilterValue(applied, activeSubFilters, 'region'),
    brand: getStringFilterValue(applied, 'brands'),
    sub_brand: getStringFilterValue(applied, 'sub_brands'),
    sku: getDimensionFilterValue(applied, activeSubFilters, 'sku'),
    category: getStringFilterValue(applied, 'category'),
    non_alcoholic: getStringFilterValue(applied, 'non_alcoholic'),
    pack_type: getDimensionFilterValue(applied, activeSubFilters, 'pack_type'),
    growth_levers: getStringFilterValue(applied, 'growth_levers'),
    beer_price_segment: getStringFilterValue(applied, 'beer_price_segment'),
    portfolios: getStringFilterValue(applied, 'portfolios'),
    channel: getDimensionFilterValue(applied, activeSubFilters, 'channel'),
  };
}
